import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 내역현황과 내역집계는 응답 필드가 같아 같은 재발급 수수료 목록을 돌려준다 (집계 기준은 현행 기능 확인 후 조정).
const VIEW_TYPES = ['내역현황', '내역집계'];
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const DATE_PATTERN = /^\d{4}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])$/;

@Controller('api/v1')
export class FnSfr04205Controller {
  @Get('/fee-records/reissue-status')
  async listReissueStatuses(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자', '임직원');
    const q = checks.queryOf(req.query);

    const viewType = q['viewType'];
    if (typeof viewType !== 'string' || viewType === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 구분을 선택해 주세요.');
    }
    if (!VIEW_TYPES.includes(viewType)) {
      throw new ApiError(422, 'INVALID_SEARCH_CONDITION', '조회 구분은 내역현황 또는 내역집계여야 합니다.');
    }

    const fromRaw = q['fromDate'];
    const toRaw = q['toDate'];
    const fromDate = typeof fromRaw === 'string' && fromRaw !== '' ? fromRaw : null;
    const toDate = typeof toRaw === 'string' && toRaw !== '' ? toRaw : null;
    if (fromDate !== null && !DATE_PATTERN.test(fromDate)) {
      throw new ApiError(422, 'INVALID_SEARCH_CONDITION', '조회 시작일 형식이 올바르지 않습니다.');
    }
    if (toDate !== null && !DATE_PATTERN.test(toDate)) {
      throw new ApiError(422, 'INVALID_SEARCH_CONDITION', '조회 종료일 형식이 올바르지 않습니다.');
    }
    if (fromDate !== null && toDate !== null && fromDate > toDate) {
      throw new ApiError(422, 'INVALID_SEARCH_CONDITION', '조회 시작일이 종료일보다 늦을 수 없습니다.');
    }

    const page = q['page'] === undefined || q['page'] === '' ? 0 : Number(q['page']);
    const size = q['size'] === undefined || q['size'] === '' ? DEFAULT_SIZE : Number(q['size']);
    if (!Number.isInteger(page) || page < 0 || !Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호나 쪽 크기가 올바르지 않습니다.');
    }
    const limited = Math.min(size, MAX_SIZE);

    return transaction(async (db) => {
      const where = `fee_type = '재발급'
        AND (CAST(:fromDate AS date) IS NULL OR registered_on >= CAST(:fromDate AS date))
        AND (CAST(:toDate AS date) IS NULL OR registered_on <= CAST(:toDate AS date))`;
      const countRows = await db.query(
        `SELECT COUNT(*) AS "total" FROM fee_record WHERE ${where}`,
        { fromDate, toDate },
      );
      const items = await db.query(
        `SELECT fee_record_id AS "feeRecordId",
                case_no AS "caseNo",
                case_name AS "caseName",
                registered_on AS "registeredOn",
                fee_amount AS "feeAmount"
           FROM fee_record
          WHERE ${where}
          ORDER BY registered_on DESC, fee_record_id DESC
          LIMIT :limit OFFSET :offset`,
        { fromDate, toDate, limit: limited, offset: page * limited },
      );
      return {
        items,
        page,
        size: limited,
        total: Number(countRows[0]['total']),
      };
    });
  }
}

