import { useState } from 'react';
import {
  Band,
  DataTable,
  DateInput,
  DateText,
  ErrorText,
  Field,
  Filters,
  Num,
  Pager,
  Select,
  Tiles,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

const PAGE_SIZE = 20;

export default function FnSfr04205Page({ role, notify }: PageProps) {
  const [viewType, setViewType] = useState('내역현황');
  const [fromDate, setFromDate] = useState('');
  const [toDate, setToDate] = useState('');
  const [applied, setApplied] = useState({ viewType: '내역현황', fromDate: '', toDate: '' });
  const [pageNo, setPageNo] = useState(0);
  const [localError, setLocalError] = useState('');

  const { data, error, loading } = useData<Page>(
    () =>
      call<Page>('GET', '/fee-records/reissue-status', role, undefined, {
        viewType: applied.viewType,
        fromDate: applied.fromDate,
        toDate: applied.toDate,
        page: pageNo,
        size: PAGE_SIZE,
      }),
    [applied, pageNo, role],
  );

  const search = () => {
    if (!viewType) {
      setLocalError('조회 구분을 선택해 주세요.');
      return;
    }
    if (fromDate && toDate && fromDate > toDate) {
      setLocalError('조회 시작일이 종료일보다 늦을 수 없습니다.');
      return;
    }
    setLocalError('');
    setPageNo(0);
    setApplied({ viewType, fromDate, toDate });
  };

  const reset = () => {
    setViewType('내역현황');
    setFromDate('');
    setToDate('');
    setLocalError('');
    setPageNo(0);
    setApplied({ viewType: '내역현황', fromDate: '', toDate: '' });
  };

  const rows: Row[] = data ? data.items : [];
  const pageSum = rows.reduce((sum, r) => sum + Number(r['feeAmount'] ?? 0), 0);

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>재발급 현황</h2>
        <Tiles
          items={[
            ['조회 건수', <Num value={data ? data.total : 0} />],
            ['현재 쪽 수수료 합계', <Num value={pageSum} />],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>재발급 내역</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="조회 구분" required>
            <Select
              value={viewType}
              onChange={setViewType}
              options={[
                ['내역현황', '내역현황'],
                ['내역집계', '내역집계'],
              ]}
            />
          </Field>
          <Field label="조회 시작일">
            <DateInput value={fromDate} onChange={setFromDate} />
          </Field>
          <Field label="조회 종료일">
            <DateInput value={toDate} onChange={setToDate} />
          </Field>
        </Filters>
        {localError ? <ErrorText text={localError} /> : null}
        {error ? <ErrorText text={error} /> : null}
        <Band total={data ? data.total : 0} />
        <DataTable
          columns={[
            { key: 'feeRecordId', label: '수수료 내역 ID' },
            { key: 'caseNo', label: '건 번호' },
            { key: 'caseName', label: '건명' },
            {
              key: 'registeredOn',
              label: '등록일자',
              render: (r) => <DateText value={r['registeredOn']} />,
            },
            {
              key: 'feeAmount',
              label: '수수료 금액',
              render: (r) => <Num value={r['feeAmount']} />,
            },
          ]}
          rows={rows}
          empty={loading ? '불러오는 중입니다.' : '조회 조건에 해당하는 데이터가 없습니다.'}
        />
        <Pager
          page={pageNo}
          size={PAGE_SIZE}
          total={data ? data.total : 0}
          onPage={setPageNo}
        />
      </section>
    </div>
  );
}
